   <View style={[s.compareCard,ds]}><View style={s.compareTitleRow}><Text style={[s.compareTitle,darkMode&&s.darkText]}>Compare with {monthName(shiftMonth(month,-1))}</Text><Text style={s.cardChevron}>›</Text></View><View style={s.compareTotals}><View><Text style={[s.compareTotalLabel,darkMode&&s.darkMuted]}>{monthName(shiftMonth(month,-1))}</Text><Text style={[s.compareTotalValue,darkMode&&s.darkText]}>{money(comparePreviousTotal)}</Text></View><View><Text style={[s.compareTotalLabel,darkMode&&s.darkMuted]}>{monthName(month)}</Text><Text style={[s.compareTotalValue,darkMode&&s.darkText]}>{money(compareCurrentTotal)}</Text></View><View><Text style={[s.compareTotalLabel,darkMode&&s.darkMuted]}>Difference</Text><Text style={[s.compareTotalValue,compareDelta>0?s.deltaUp:compareDelta<0?s.deltaDown:null]}>{compareDelta>0?'+':''}{money(compareDelta)}</Text></View></View><View style={s.compareSummary}><Text style={s.compareMissing}>{missingThisMonth.length} missing</Text><Text style={s.compareNew}>{newThisMonth.length} new</Text><Text style={s.compareChanged}>{changedThisMonth.length} changed</Text></View>{missingThisMonth.map(x=><Text key={'m'+x.rowId} style={[s.compareLine,s.compareLineMissing]}>Missing · {x.payee} · {money(x.amount)}</Text>)}{newThisMonth.map(x=><Text key={'n'+x.rowId} style={[s.compareLine,s.compareLineNew]}>New · {x.payee} · {money(x.amount)}</Text>)}{changedThisMonth.map(({current,previous})=><Text key={'c'+current.rowId} style={[s.compareLine,s.compareLineChanged]}>Changed · {current.payee} · {money(previous.amount)} → {money(current.amount)}</Text>)}</View>
